'use strict';

const _get = require('lodash/get');
const _setWith = require('lodash/setWith');

/**
 * Обфусцирует чувствительные данные по переданным путям в record.
 *
 * Пример подключения:
 *   require('@yandex-int/yandex-logger/middleware/secure-field')({
 *       fields: ['req.user.password']
 *   });
 *
 * Пример лога:
 *   logger.info({ req: { user: { password: 'qwerty' }}}
 *
 *   output:
 *      {"req":{"user":{"password":"qweXXX"}}}
 *
 * @param {Object} [config]
 * @returns {Function}
 * @see https://wiki.yandex-team.ru/logfeller/security/
 */
module.exports = config => {
    config = config || {};

    let fields = config.fields || [];
    let secureValue = config.secureValue || defaultSecureValue;

    /**
     * @param {Object} record
     * @returns {undefined}
     */
    return record => {
        for (let field of fields) {
            let value = _get(record, field);

            if (typeof value === 'string') {
                let newValue = secureValue(value);
                if (newValue !== value) {
                    _setWith(record, field, newValue, value => {
                        return Object.assign({}, value);
                    });
                }
            }
        }
    };
};

/**
 * @param {String} value
 * @returns {String}
 */
function defaultSecureValue(value) {
    let len = value.length;
    let center = Math.floor(len / 2);
    return value.slice(0, center) + 'X'.repeat(len - center);
}
